"""Canonical label table and per-model class maps (vendored JSON, regenerated by scripts/ctseg_build_resources.py)."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import lru_cache
from importlib import resources


@dataclass(frozen=True)
class Label:
    id: int
    name: str
    display: str
    rgb: tuple[int, int, int]
    kind: str  # bone | muscle | fat | vessel | air | heart | other (used by QC)
    snomed: dict | None


def _load(name: str) -> dict:
    return json.loads(resources.files("emgmirror.ctseg.resources").joinpath(name).read_text())


@lru_cache(maxsize=1)
def table() -> dict[str, Label]:
    return {e["name"]: Label(e["id"], e["name"], e["display"], tuple(e["rgb"]), e["kind"], e["snomed"])
            for e in _load("label_table.json")["labels"]}


@lru_cache(maxsize=1)
def by_id() -> dict[int, Label]:
    return {lab.id: lab for lab in table().values()}


@lru_cache(maxsize=1)
def task_classes() -> dict[str, dict[int, str]]:
    """{"totalsegmentator:total": {1: "spleen", ...}, "moose:clin_ct_peripheral_bones": {...}, ...}"""
    return {src: {int(k): v for k, v in m.items()} for src, m in _load("task_classes.json").items()}


def classes(source: str) -> dict[int, str]:
    try:
        return task_classes()[source]
    except KeyError:
        raise KeyError(f"no class map for '{source}'") from None


def label(name: str) -> Label:
    try:
        return table()[name]
    except KeyError:
        raise KeyError(f"'{name}' is not in the canonical label table; regenerate it with "
                       "scripts/ctseg_build_resources.py") from None
